@brief
Utilities related to ASL internally.
They can also be used by end-users.

@brief
Set a buffer with fill value.

@param
dest
Destination buffer.

@param
value
Fill value.

if ( dest.ptr ) {
    for ( size_t i = 0 ; i < dest.size ; ++i ) {
        dest.ptr[i] = value;
    }
}

@brief
Set a buffer with fill value.

@param
dest
Destination buffer.

@param
src
Source buffer.

const size_t copy_size = dest.size < src.size ? dest.size : src.size;
if ( dest.ptr && src.ptr ) {
    for ( size_t i = 0 ; i < copy_size ; ++i ) {
        dest.ptr[i] = src.ptr[i];
    }
}

@brief
Initialize (resets) the circular buffer elements.

@param
ptr_cbuf
Pointer to circular buffer.

@return
asl_cbuf_error_ok           - Success.
asl_cbuf_error_param        - NULL pointer or zero sized buffer or other parameter inconsistency.

asl_cbuf_error_n err = asl_cbuf_error_param;
size_t i = 0;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
if ( ptr_cbuf && ptr_cbuf->mem && ptr_cbuf->size_mem ) {
#endif
    ptr_cbuf->front = 0;
    ptr_cbuf->rear = 0;
    for ( i = 0 ; i < ptr_cbuf->size_mem ; ++i ) {
        ptr_cbuf->mem[i] = 0;
    }
    err = asl_cbuf_error_ok;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
}
#endif
return err;

@brief
Enqueues the requested number of elements into circular buffer.

@param
ptr_cbuf
Pointer to circular buffer.

@param
buffer
A buffer containing data to be enqueued.

@param
req_enqueue
The number of elements to be enqueued.

@return
asl_cbuf_error_ok           - Success.
asl_cbuf_error_param        - NULL pointer or zero sized buffer or other parameter inconsistency.
asl_cbuf_error_forbidden    - Not enough free space in circular buffer for requested number of elements. Prevents overflow.

asl_cbuf_error_n err = asl_cbuf_error_param;
size_t i = 0;
size_t rear = 0;
size_t capacity  = 0;
size_t available_to_write = 0;
size_t new_rear = 0;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
if ( ptr_cbuf && ptr_cbuf->mem && ptr_cbuf->size_mem && ( ptr_cbuf->front < ptr_cbuf->size_mem ) && ( ptr_cbuf->rear < ptr_cbuf->size_mem ) ) {
    if ( buffer.ptr && buffer.size && req_enqueue && ( req_enqueue < ptr_cbuf->size_mem ) && ( req_enqueue <= buffer.size ) ) {
#endif
        rear = ptr_cbuf->rear;
        capacity = ptr_cbuf->size_mem;
        available_to_write = available_write(ptr_cbuf->front, rear, capacity);
        if ( req_enqueue <= available_to_write ) {
            new_rear = circular_next(rear, req_enqueue, capacity);
            do {
                ptr_cbuf->mem[rear] = buffer.ptr[i++];
                rear = circular_next(rear, 1, capacity);
            } while ( rear != new_rear );
            ptr_cbuf->rear = rear;
            err = asl_cbuf_error_ok;
        }
        else {
            err = asl_cbuf_error_forbidden;
        }
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
    }
}
#endif
return err;

@brief
Dequeues the requested number of elements from circular buffer.

@param
ptr_cbuf
Pointer to circular buffer.

@param
buffer
A buffer to which data will be dequeued.

@param
req_dequeue
The number of elements to be dequeued.

@return
asl_cbuf_error_ok           - Success.
asl_cbuf_error_param        - NULL pointer or zero sized buffer or other parameter inconsistency.
asl_cbuf_error_forbidden    - Requested number of elements not present in circular buffer. Prevents underflow.

asl_cbuf_error_n err = asl_cbuf_error_param;
size_t i = 0;
size_t front = 0;
size_t capacity = 0;
size_t available_to_read = 0;
size_t new_front = 0;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
if ( ptr_cbuf && ptr_cbuf->mem && ptr_cbuf->size_mem && ( ptr_cbuf->front < ptr_cbuf->size_mem ) && ( ptr_cbuf->rear < ptr_cbuf->size_mem ) ) {
    if ( buffer.ptr && buffer.size && req_dequeue && ( req_dequeue < ptr_cbuf->size_mem ) && ( req_dequeue <= buffer.size ) ) {
#endif
        front = ptr_cbuf->front;
        capacity = ptr_cbuf->size_mem;
        available_to_read = available_read(front, ptr_cbuf->rear, capacity);
        if ( req_dequeue <= available_to_read ) {
            new_front = circular_next(front, req_dequeue, capacity);
            do {
                buffer.ptr[i++] = ptr_cbuf->mem[front] ;
                front = circular_next(front, 1, capacity);
            } while ( front != new_front );
            ptr_cbuf->front = front;
            err = asl_cbuf_error_ok;
        }
        else {
            err = asl_cbuf_error_forbidden;
        }
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
    }
}
#endif
return err;

@brief
Dequeues the requested number of elements from circular buffer.

@param
ptr_cbuf
Pointer to circular buffer.

@param
buffer
A buffer to which data will be previewed.

@param
req_preview
The number of elements to be previewed.

@return
asl_cbuf_error_ok           - Success.
asl_cbuf_error_param        - NULL pointer or zero sized buffer or other parameter inconsistency.
asl_cbuf_error_forbidden    - Requested number of elements not present in circular buffer. Prevents underflow.

asl_cbuf_error_n err = asl_cbuf_error_param;
size_t i = 0;
size_t front = 0;
size_t capacity = 0;
size_t available_to_read = 0;
size_t new_front = 0;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
if ( ptr_cbuf && ptr_cbuf->mem && ptr_cbuf->size_mem && ( ptr_cbuf->front < ptr_cbuf->size_mem ) && ( ptr_cbuf->rear < ptr_cbuf->size_mem ) ) {
    if ( buffer.ptr && buffer.size && req_preview && ( req_preview < ptr_cbuf->size_mem ) && ( req_preview <= buffer.size ) ) {
#endif
        front = ptr_cbuf->front;
        capacity = ptr_cbuf->size_mem;
        available_to_read = available_read(front, ptr_cbuf->rear, capacity);
        if ( req_preview <= available_to_read ) {
            new_front = circular_next(front, req_preview, capacity);
            do {
                buffer.ptr[i++] = ptr_cbuf->mem[front] ;
                front = circular_next(front, 1, capacity);
            } while ( front != new_front );
            // We don't update the actual CBUF front since this is just a preview.
            err = asl_cbuf_error_ok;
        }
        else {
            err = asl_cbuf_error_forbidden;
        }
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
    }
}
#endif
return err;

@brief
Tells how many elements are present and thus can be read in circular buffer.

@param
ptr_cbuf
Pointer to circular buffer.

@param
available_to_read
When parameters are correct, the number of elements possible to read will be updated into this pointer.

@return
asl_cbuf_error_ok           - Success.
asl_cbuf_error_param        - NULL pointer or zero sized buffer or other parameter inconsistency.

asl_cbuf_error_n err = asl_cbuf_error_param;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
if ( ptr_cbuf && ptr_cbuf->mem && ptr_cbuf->size_mem && ( ptr_cbuf->front < ptr_cbuf->size_mem ) && ( ptr_cbuf->rear < ptr_cbuf->size_mem ) && available_to_read ) {
#endif
    *available_to_read = available_read(ptr_cbuf->front, ptr_cbuf->rear, ptr_cbuf->size_mem);
    err = asl_cbuf_error_ok;
#if ASL_CBUF_ENABLE_PARAM_CHECK == 1
}
#endif
return err;

@brief
